solutionCode:
abstract class GamePiece {
    abstract val name: String
    abstract val points: Int

    fun describe(): String {
        return "$name is worth $points points"
    }
}

class Cone : GamePiece() {
    override val name = "Cone"
    override val points = 3
}

class Cube : GamePiece() {
    override val name = "Cube"
    override val points = 4
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testConeName() {
        val cone = Cone()
        Assert.assertEquals("Cone", cone.name)
    }

    @Test
    fun testConePoints() {
        val cone = Cone()
        Assert.assertEquals(3, cone.points)
    }

    @Test
    fun testConeDescribe() {
        val cone = Cone()
        Assert.assertEquals("Cone is worth 3 points", cone.describe())
    }

    @Test
    fun testCubeName() {
        val cube = Cube()
        Assert.assertEquals("Cube", cube.name)
    }

    @Test
    fun testCubePoints() {
        val cube = Cube()
        Assert.assertEquals(4, cube.points)
    }

    @Test
    fun testCubeDescribe() {
        val cube = Cube()
        Assert.assertEquals("Cube is worth 4 points", cube.describe())
    }
}
